// Shader by @RobinsSecret on twt


#define TWO_PI 6.28318530718
#define PI 3.14159

//  Function from Iñigo Quiles
//  https://www.shadertoy.com/view/MsS3Wc
vec3 hsb2rgb(vec3 c){
    vec3 rgb = clamp(abs(mod(c.x*6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0)
    - 1.0, 0.0, 1.0);
    rgb = rgb*rgb*(3.0-2.0*rgb);
    return c.z * mix(vec3(1.0), rgb, c.y);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    //uv = fract(uv * 1.5) - 0.5;
    vec3 color = vec3(1.0);

    float radius = length(uv) * 2.0;

    float bigCircleR = 2.1;
    float bigCircler = 1.6;

    float midCircleR = 1.2;
    float midCircler = 0.8;

    float smolCircleR = 0.5;
    float smolCircler = 0.2;

    bigCircleR += sin(iTime);
    bigCircler += sin(iTime);

    midCircleR += cos(iTime);
    midCircler += cos(iTime);

    smolCircleR += abs(sin(iTime));
    smolCircler += abs(sin(iTime));

    // big circle
    if(radius < bigCircleR && radius > bigCircler){
        float angle = atan(uv0.y, uv0.x);
        angle += (PI / 8.0) * iTime;
        color = hsb2rgb(vec3((angle/TWO_PI)+0.5, radius, 1.0));
    // medium circle
    } else if(radius < midCircleR && radius > midCircler){
        float angle = atan(uv0.y, uv0.x);
        angle -= (PI / 4.0) * iTime;
        color = hsb2rgb(vec3((angle/TWO_PI)+0.5, radius, 1.0));
    // small circle
    } else if (radius < smolCircleR && radius > smolCircler) {
        float angle = atan(uv0.y, uv0.x);
        angle += (PI / 2.0) * iTime;
        color = hsb2rgb(vec3((angle/TWO_PI)+0.5, radius, 1.0));
    } else if (radius < smolCircleR) {
        color = vec3(0.0);
    } else if (radius < midCircleR) {
        color = vec3(1.0);
    } else if (radius < bigCircleR) {
        color = vec3(0.0);
    }

    fragColor = vec4(color, 1.0);
}
